  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCompiler = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

/** Rejects invalid input via ToolResponse; throws only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const validate = this.resolveValidator(tool);
  if (!validate(input)) {
    const violations = formatValidationErrors(validate.errors);
    log.warn('tool', 'validation failed', {name, violations});
    return {result: `Invalid input for tool "${name}": ${violations.join('; ')}`};
  }
  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);

